"""Reference bodies (what a good model writes) for the Todo UI plan."""
UI_BODIES = {'todo.ui_button:render_button': 'opening = "<form method=\'post\' action=\'/" + action + "\'>"\nhidden = "<input type=\'hidden\' name=\'id\' value=\'" + str(task_id) + "\'>"\nreturn opening + hidden + "<button>" + label + "</button></form>"', 'todo.ui_task:render_task': 'import html\nlabel = html.escape(task["text"])\nif task["done"]: label = "<s>" + label + "</s>"\ndone_button = render_button("done", task["id"], "Done")\nremove_button = render_button("remove", task["id"], "Remove")\nreturn "<li>" + label + " " + done_button + " " + remove_button + "</li>"', 'todo.ui_list:render_list': 'if len(tasks) == 0: return "<p>No tasks yet.</p>"\nrows = ""\nfor task in tasks:\n    rows = rows + render_task(task)\nreturn "<ul>" + rows + "</ul>"', 'todo.ui_page:render_page': 'summary = summarize(tasks)\nform = "<form method=\'post\' action=\'/add\'><input name=\'text\' placeholder=\'new task\' required><button>Add</button></form>"\nhead = "<!doctype html><meta charset=\'utf-8\'><title>Todo</title><style>form{display:inline}li{margin:6px 0}</style><h1>Todo</h1>"\nreturn head + "<p>" + summary + "</p>" + form + render_list(tasks)', 'todo.ui_add:handle_add': 'return add_task(tasks, form["text"])', 'todo.ui_done:handle_done': 'return complete_task(tasks, int(form["id"]))', 'todo.ui_remove:handle_remove': 'return remove_task(tasks, int(form["id"]))'}
